(()=>{const order=['portrait','front','left','back'],names={portrait:'大头像',front:'全身正面',left:'侧面',back:'背面'};function apply(c,angle,job){const clone=x=>JSON.parse(JSON.stringify(x)),old=activeMulti(c),entry=old?clone(old):{jobs:{},time:new Date().toLocaleTimeString('zh-CN')};entry.jobs??={};entry.jobs[angle]={...job,angle,...(angle==='portrait'?{identity_master:true}:{})};entry.time=new Date().toLocaleTimeString('zh-CN');entry.uploaded_view=angle;delete entry.auto_run_id;c.multi??=[];c.multi.push(entry);c.multiActive=c.multi.length-1;c.reference_images??={};c.reference_images[angle]=job.image_url;if(angle==='portrait'){c.identityPortrait={...job};c.portraitJob={...job};c.portraitVersions??=[];c.portraitVersions.push({...job});c.portraitConfirmed=true;c.portraitConfirmedId=job.id;if(c.portraitCandidates){c.portraitCandidateHistory??=[];c.portraitCandidateHistory.push(c.portraitCandidates);delete c.portraitCandidates;}}if(angle==='front'){c.versions??=[];c.versions.push({...job,job_id:job.id,time:new Date().toLocaleTimeString('zh-CN'),createdAt:Date.now()});c.active=c.versions.length-1;c.frontJob={...job};c.confirmed=true;c.confirmedVersion=c.active;entry.reference_job_id=job.id;}c.stale=true;if(c.oneClick&&!['running','stopping'].includes(c.oneClick.status)){c.oneClick.tasks??={};c.oneClick.tasks[angle]={...job};if(angle==='front')c.oneClick.reference_job_id=job.id;}c.view='multi';return c;}
function draw(){if(tab!==0)return;const c=data.characters[ci];if(!c||c.specialReference)return;document.querySelectorAll('#panel .angle-grid .angle').forEach((box,i)=>{const angle=order[i];if(!angle||box.querySelector('[data-upload-view]'))return;const button=document.createElement('button');button.dataset.uploadView=angle;button.textContent='上传替换';button.style.cssText='width:auto;align-self:center;padding:8px 12px;margin:8px 0';button.disabled=roleIsBusy(c);const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';input.hidden=true;button.onclick=()=>input.click();input.onchange=async()=>{const file=input.files[0];if(!file)return;button.disabled=true;button.textContent='正在上传…';const project=data.project_id;try{if(file.size>10*1024*1024)throw Error('图片不能超过10MB');await ensureProjectSaved();const image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const job=await frontFetch('/api/character-reference-upload',{project_id:project,character_id:String(c.id||c.character_id||c.name),layout:'single',image});if(project!==data.project_id)throw Error('项目已切换，请回到原项目重新绑定');apply(c,angle,job);save();await ensureProjectSaved();render();toast('已替换'+names[angle]+'，原图保留历史版本');}catch(e){toast(e.message);button.disabled=false;button.textContent='上传替换';}finally{input.value='';}};box.append(button,input);});}const previous=characters;characters=function(){previous();draw();};render();})();